import{_ as a,o as s,c as i,a5 as o}from"./chunks/framework.B6tQOu6W.js";const r="/assets/modele-step-1.DMO-nScm.jpg",l="/assets/modele-step-3.C1E91fC9.jpg",t="/assets/modele-step-4.BKCTPIg-.jpg",n="/assets/modele-step-5.BgEiLSXz.jpg",u="/assets/modele-step-6.BvPjpq5-.jpg",d="/assets/modele-step-7.DEARdvGp.jpg",c="/assets/edit-hostname.DTF6rBQh.jpg",C=JSON.parse(`{"title":"TP1. Créer une VM sur la ferme à partir d'un modèle.","description":"Dans ce TP nous allons voir comment créer une VM (machine virtuelle) sur la ferme VMWare du BTS SIO à Angers depuis un modèle.","frontmatter":{"description":"Dans ce TP nous allons voir comment créer une VM (machine virtuelle) sur la ferme VMWare du BTS SIO à Angers depuis un modèle."},"headers":[],"relativePath":"tp/devops/serveur/tp1alt.md","filePath":"tp/devops/serveur/tp1alt.md","lastUpdated":1741429694000}`),p={name:"tp/devops/serveur/tp1alt.md"};function m(h,e,v,g,b,f){return s(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="tp1-creer-une-vm-sur-la-ferme-a-partir-d-un-modele" tabindex="-1">TP1. Créer une VM sur la ferme à partir d&#39;un modèle. <a class="header-anchor" href="#tp1-creer-une-vm-sur-la-ferme-a-partir-d-un-modele" aria-label="Permalink to &quot;TP1. Créer une VM sur la ferme à partir d&#39;un modèle.&quot;">​</a></h1><details class="details custom-block"><summary>Sommaire</summary><nav class="table-of-contents"><ul><li><a href="#objectifs">Objectifs</a></li><li><a href="#pre-requis">Pré-requis</a></li><li><a href="#les-etapes">Les étapes</a><ul><li><a href="#_0-creer-la-vm">0. Créer la VM</a></li><li><a href="#_1-choix-du-modele-dans-la-liste">1. Choix du modèle dans la liste</a></li><li><a href="#_3-nom-de-la-vm-et-emplacement">3. Nom de la VM et emplacement</a></li><li><a href="#_4-configuration-de-la-vm">4. Configuration de la VM</a></li><li><a href="#_5-configuration-du-stockage">5. Configuration du stockage</a></li><li><a href="#_6-personnalisation-de-la-vm">6. Personnalisation de la VM</a></li><li><a href="#_7-choix-du-vlan">7. Choix du VLAN</a></li></ul></li><li><a href="#premier-demarrage">Premier démarrage</a><ul><li><a href="#changer-la-configuration-reseau">Changer la configuration réseau</a></li><li><a href="#changer-le-mot-de-passe-de-l-utilisateur-root">Changer le mot de passe de l&#39;utilisateur root</a></li><li><a href="#creer-un-compte-utilisateur">Créer un compte utilisateur</a></li><li><a href="#vous-ajouter-au-groupe-sudo">Vous ajouter au groupe sudo</a></li><li><a href="#mettre-a-jour-le-systeme">Mettre à jour le système</a></li><li><a href="#changer-le-nom-de-la-machine">Changer le nom de la machine</a></li></ul></li><li><a href="#securisation-de-l-acces-ssh">Sécurisation de l&#39;accès SSH</a></li><li><a href="#conclusion">Conclusion</a></li></ul></nav></details><h2 id="objectifs" tabindex="-1">Objectifs <a class="header-anchor" href="#objectifs" aria-label="Permalink to &quot;Objectifs&quot;">​</a></h2><p>Dans ce TP nous allons voir comment créer une VM sur la ferme VMWare du BTS SIO à Angers depuis un modèle. L&#39;idée de ce TP est de comprendre la démarche à suivre.</p><div class="danger custom-block"><p class="custom-block-title">👋 Attention</p><p>La ferme est un équipement partagé par l&#39;ensemble des étudiants du BTS (1ère et 2ème année). Il est donc important de respecter quelques règles d&#39;utilisation pour une utilisation optimale de la ferme, et surtout <strong>dans l&#39;intérêt de tous</strong>.</p></div><p>Dans ce TP nous allons utiliser un modèle déjà créé. Si vous souhaitez créer une VM sans modèle, vous pouvez suivre le <a href="./tp1.html">TP1</a>.</p><h2 id="pre-requis" tabindex="-1">Pré-requis <a class="header-anchor" href="#pre-requis" aria-label="Permalink to &quot;Pré-requis&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Uniquement disponible pour le Lycée / VPN</p><p>Pour réaliser ce TP vous devez :</p><ul><li>Être connecté à la ferme du BTS SIO à Angers (ou via le VPN).</li><li>Avoir un compte sur L&#39;AD.</li></ul></div><h2 id="les-etapes" tabindex="-1">Les étapes <a class="header-anchor" href="#les-etapes" aria-label="Permalink to &quot;Les étapes&quot;">​</a></h2><p>Vous retrouverez ci-dessous les étapes à suivre pour réaliser une machine depuis un modèle.</p><div class="danger custom-block"><p class="custom-block-title">👋 Attention</p><p>Créer une VM à partir d&#39;un modèle est plus rapide que de créer une VM à partir de zéro. Cependant, un modèle impose la personnalisation de la VM en fin de procédure. À savoir :</p><ul><li>Configuration du VLAN.</li><li>Configuration de l&#39;IP.</li><li>Configuration du nom de la machine.</li><li>Changement du mot de passe <code>root</code>.</li><li>Mise à jour des paquets de la machine.</li></ul></div><h3 id="_0-creer-la-vm" tabindex="-1">0. Créer la VM <a class="header-anchor" href="#_0-creer-la-vm" aria-label="Permalink to &quot;0. Créer la VM&quot;">​</a></h3><p>Pour créer une VM, il faut :</p><ul><li>Sélectionner le modèle dans le dossier « MODELES ».</li><li>Clique droit sur la VM que vous souhaitez prendre comme modèle</li><li>Puis « Nouvelle VM à partir de ce modèle ».</li></ul><h3 id="_1-choix-du-modele-dans-la-liste" tabindex="-1">1. Choix du modèle dans la liste <a class="header-anchor" href="#_1-choix-du-modele-dans-la-liste" aria-label="Permalink to &quot;1. Choix du modèle dans la liste&quot;">​</a></h3><p><img src="'+r+'" alt="Type de création" loading="lazy"></p><div class="tip custom-block"><p class="custom-block-title">📝 Remarque</p><p>Le nom du modèle est composé de la façon suivante :</p><ul><li><code>MODELE-</code> : Préfixe.</li><li><code>OS</code> : Nom de l&#39;OS (exemple : <code>debian</code>).</li><li><code>VERSION</code> : Version de l&#39;OS (exemple : <code>11.5</code>).</li><li><code>UTILISATEUR</code> : Nom de l&#39;utilisateur pour utiliser le modèle (exemple: <code>root</code>).</li><li><code>Mot de passe</code> : Mot de passe de l&#39;utilisateur pour utiliser le modèle (exemple : <code>root</code>). <strong>Ce mot de passe est à changer une fois la VM créée.</strong></li></ul></div><h3 id="_3-nom-de-la-vm-et-emplacement" tabindex="-1">3. Nom de la VM et emplacement <a class="header-anchor" href="#_3-nom-de-la-vm-et-emplacement" aria-label="Permalink to &quot;3. Nom de la VM et emplacement&quot;">​</a></h3><p><img src="'+l+'" alt="Nom de la VM et emplacement" loading="lazy"></p><h3 id="_4-configuration-de-la-vm" tabindex="-1">4. Configuration de la VM <a class="header-anchor" href="#_4-configuration-de-la-vm" aria-label="Permalink to &quot;4. Configuration de la VM&quot;">​</a></h3><p><img src="'+t+'" alt="Ressources" loading="lazy"></p><h3 id="_5-configuration-du-stockage" tabindex="-1">5. Configuration du stockage <a class="header-anchor" href="#_5-configuration-du-stockage" aria-label="Permalink to &quot;5. Configuration du stockage&quot;">​</a></h3><p><img src="'+n+'" alt="Stockage" loading="lazy"></p><h3 id="_6-personnalisation-de-la-vm" tabindex="-1">6. Personnalisation de la VM <a class="header-anchor" href="#_6-personnalisation-de-la-vm" aria-label="Permalink to &quot;6. Personnalisation de la VM&quot;">​</a></h3><p><img src="'+u+'" alt="Réseau" loading="lazy"></p><h3 id="_7-choix-du-vlan" tabindex="-1">7. Choix du VLAN <a class="header-anchor" href="#_7-choix-du-vlan" aria-label="Permalink to &quot;7. Choix du VLAN&quot;">​</a></h3><p>N&#39;oubliez pas de choisir le VLAN pour votre VM.</p><p><img src="'+d+'" alt="VLAN" loading="lazy"></p><h2 id="premier-demarrage" tabindex="-1">Premier démarrage <a class="header-anchor" href="#premier-demarrage" aria-label="Permalink to &quot;Premier démarrage&quot;">​</a></h2><p>Maintenant que votre VM est créée, il faut la démarrer, comme pour n&#39;importe quelle autre VM.</p><p>Cependant, vu qu&#39;il s&#39;agit d&#39;une VM créée à partir d&#39;un modèle, il y a quelques étapes à suivre pour la configurer.</p><ul><li>Changer la configuration réseau.</li><li>Changer le mot de passe de l&#39;utilisateur <code>root</code>.</li><li>Vous créez un compte utilisateur.</li><li>Mettre à jour le système.</li></ul><h3 id="changer-la-configuration-reseau" tabindex="-1">Changer la configuration réseau <a class="header-anchor" href="#changer-la-configuration-reseau" aria-label="Permalink to &quot;Changer la configuration réseau&quot;">​</a></h3><p>Pour cette étape vous pouvez utiliser l&#39;outil disponible dans l&#39;aide mémoire :</p><p>En utilisant l&#39;aide mémoire <a href="/cheatsheets/serveur/debian-reseau.html">disponible ici</a>, générer une nouvelle adresse IP pour votre serveur.</p><p>Une fois les lignes <code>address</code> et <code>gateway</code> modifié dans le fichier <code>/etc/network/interfaces</code>, vous pouvez redémarrer votre serveur pour que les modifications soient prises en compte.</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reboot</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Une fois suivi vous pouvez vérifier que votre serveur a bien une nouvelle adresse IP en utilisant la commande <code>ip a</code>.</p><p>Vous pouvez aussi vérifier l&#39;accès à internet en utilisant la commande <code>ping google.com</code></p><div class="tip custom-block"><p class="custom-block-title">Ça ne fonctionne pas ?</p><ul><li>Vérifier que votre VM est bien connectée au bon VLAN.</li><li>Vérifier que vous n&#39;avez pas déjà utilisé cette adresse IP.</li><li>Vérifier le serveur DNS (dans les fichiers <code>/etc/resolv.conf</code> et <code>/etc/network/interfaces</code>).</li></ul></div><h3 id="changer-le-mot-de-passe-de-l-utilisateur-root" tabindex="-1">Changer le mot de passe de l&#39;utilisateur <code>root</code> <a class="header-anchor" href="#changer-le-mot-de-passe-de-l-utilisateur-root" aria-label="Permalink to &quot;Changer le mot de passe de l&#39;utilisateur `root`&quot;">​</a></h3><p>Pour changer le mot de passe de l&#39;utilisateur, <code>root</code> vous pouvez utiliser la commande <code>passwd</code>.</p><h3 id="creer-un-compte-utilisateur" tabindex="-1">Créer un compte utilisateur <a class="header-anchor" href="#creer-un-compte-utilisateur" aria-label="Permalink to &quot;Créer un compte utilisateur&quot;">​</a></h3><p>Pour créer un compte utilisateur, vous pouvez utiliser la commande <code>adduser &lt;votre-nom-d-utilisateur&gt;</code>.</p><div class="tip custom-block"><p class="custom-block-title">📝 Remarque</p><p>Il est important de créer un compte utilisateur pour ne pas utiliser le compte <code>root</code> pour se connecter.</p></div><h3 id="vous-ajouter-au-groupe-sudo" tabindex="-1">Vous ajouter au groupe sudo <a class="header-anchor" href="#vous-ajouter-au-groupe-sudo" aria-label="Permalink to &quot;Vous ajouter au groupe sudo&quot;">​</a></h3><p>Pour pouvoir passer des commandes en tant que super utilisateur, vous pouvez ajouter votre utilisateur au groupe <code>sudo</code>.</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">usermod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -aG</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sudo</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">votre-nom-d-utilsateu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="mettre-a-jour-le-systeme" tabindex="-1">Mettre à jour le système <a class="header-anchor" href="#mettre-a-jour-le-systeme" aria-label="Permalink to &quot;Mettre à jour le système&quot;">​</a></h3><p>Maintenant que votre VM est prête, il faut mettre à jour le système.</p><p>Pour cela vous pouvez utiliser la commande :</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="changer-le-nom-de-la-machine" tabindex="-1">Changer le nom de la machine <a class="header-anchor" href="#changer-le-nom-de-la-machine" aria-label="Permalink to &quot;Changer le nom de la machine&quot;">​</a></h3><p>Par défaut le nom de la machine sera celui du modèle. Pour changer le nom de la machine, vous pouvez utiliser la commande <code>hostnamectl</code>.</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Définir le nom de la machine</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hostnamectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set-hostname</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> votre-nouveau-nom-de-machine</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Puis changer le fichiers <code>/etc/hosts</code> pour que le nom de la machine soit correct. Dans mon cas je vais remplacer :</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">192.168.137.10</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> modele-debian-11</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Par :</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">192.168.MON.IP</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vbrosseau-demo-modele</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Vous pouvez utiliser <code>vim</code> ou <code>nano</code> pour modifier le fichier.</p><details class="details custom-block"><summary>le fichiers /etc/hosts avant modification</summary><p><img src="'+c+'" alt="Fichier /etc/hosts" loading="lazy"></p></details><h2 id="securisation-de-l-acces-ssh" tabindex="-1">Sécurisation de l&#39;accès SSH <a class="header-anchor" href="#securisation-de-l-acces-ssh" aria-label="Permalink to &quot;Sécurisation de l&#39;accès SSH&quot;">​</a></h2><p>Nous l&#39;avons vu dans <a href="./tp1b.html#ajouter-votre-clé-publique-sur-votre-serveur">le TP précédent</a>, il est important de sécuriser l&#39;accès SSH à votre serveur. Nous allons donc réaliser les mêmes étapes que dans le TP précédent à savoir :</p><ul><li>Interdire la connexion en tant que <code>root</code> (<code>PermitRootLogin no</code>).</li><li>Interdire la connexion avec un mot de passe (<code>PasswordAuthentication no</code>).</li></ul><div class="danger custom-block"><p class="custom-block-title">👋 Attention</p><p>Une fois ces paramètres modifiés, votre serveur ne sera plus accessible en mode mot de passe. Il est donc important de réaliser <strong>un échange de clés au préalable</strong> (via la commande <code>ssh-copy-id &lt;votre-utilisateur&gt;@&lt;votre-ip&gt;</code> depuis votre machine).</p></div><p>Pour cela vous pouvez éditer le fichier <code>/etc/ssh/sshd_config</code> et modifier les lignes relatives à ces paramètres (<code>vim /etc/ssh/sshd_config</code>).</p><details class="details custom-block"><summary>Aller plus loin</summary><p>Vous pouvez aussi changer le port d&#39;écoute du serveur SSH pour éviter les attaques par force brute. Pour cela vous pouvez modifier la ligne <code>Port 22</code> par un autre port (exemple : <code>Port 2222</code>).</p><p>Une fois modifié, vous pourrez accéder à votre serveur en utilisant la commande <code>ssh -p 2222 &lt;votre-utilisateur&gt;@&lt;votre-ip&gt;</code>.</p></details><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Vous avez maintenant une VM fonctionnelle, vous pouvez maintenant l&#39;utiliser pour vos projets.</p>',69)])])}const q=a(p,[["render",m]]);export{C as __pageData,q as default};
